:root {
  --green-dark: #2d6a4f;
  --green-mid: #52b788;
  --green-light: #d8f3dc;
  --green-pale: #f0faf2;
  --amber: #e76f00;
  --amber-light: #fff3e0;
  --text-dark: #1b2e22;
  --text-mid: #4a6651;
  --text-muted: #7a9e82;
  --white: #ffffff;
  --border: #b7dfc2;
  --featured-bg: #fff8e1;
  --featured-border: #e76f00;
}

.stall-card {
  width: 500px;
  background: var(--white);
  border-radius: 16px;
  border: 2px solid var(--border);
  overflow: hidden;
  margin: 20px auto;
}

.stall-header {
  background: var(--green-dark);
  padding: 14px 18px;
  display: flex;
  align-items: center;
  gap: 14px;
}

.stall-badge {
  background: var(--amber);
  color: var(--white);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  padding: 6px 10px;
  border-radius: 8px;
  flex-shrink: 0;
}

.stall-title {
  flex: 1;
}

.vendor-name {
  font-size: 20px;
  font-weight: 800;
  color: var(--white);
  margin: 0 0 2px 0;
  line-height: 1.2;
}

.vendor-tagline {
  font-size: 12px;
  color: var(--green-mid);
  margin: 0;
  font-weight: 500;
}

.open-tag {
  background: var(--green-mid);
  color: var(--white);
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  padding: 5px 10px;
  border-radius: 20px;
  flex-shrink: 0;
}

.stall-body {
  padding: 16px 18px;
  background: var(--green-pale);
}

.produce-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 8px;
  margin-bottom: 14px;
}

.produce-item {
  background: var(--white);
  border: 1.5px solid var(--border);
  border-radius: 10px;
  padding: 10px 8px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.produce-item.featured {
  background: var(--featured-bg);
  border-color: var(--featured-border);
}

.produce-icon {
  font-size: 22px;
  line-height: 1;
}

.produce-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-dark);
  text-align: center;
}

.produce-price {
  font-size: 13px;
  font-weight: 800;
  color: var(--green-dark);
}

.produce-item.featured .produce-price {
  color: var(--amber);
}

.stall-footer {
  background: var(--white);
  border: 1.5px solid var(--border);
  border-radius: 10px;
  padding: 10px 14px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.footer-info {
  display: flex;
  flex-direction: column;
  gap: 2px;
  flex: 1;
  align-items: center;
}

.info-label {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.info-value {
  font-size: 12px;
  font-weight: 600;
  color: var(--text-dark);
}

.footer-divider {
  width: 1.5px;
  height: 32px;
  background: var(--border);
  flex-shrink: 0;
}
